<div class="heading"><div><p class="eyebrow">ACCOUNT</p><h1><?= $e($user['display_name']) ?></h1><p class="muted">账号 ID：<?= $e($user['id']) ?></p></div></div><div class="grid two"><section class="card"><h2>基本资料</h2><form method="post" action="/account/profile"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><label>昵称<input name="name" value="<?= $e($user['display_name']) ?>" maxlength="80" required></label><button>保存资料</button></form><p>邮箱：<?= $e($user['email']??'尚未绑定') ?><?= $user['email_verified']?'（已验证）':'' ?></p><?php if(!$user['email']): ?><form method="post" action="/account/email" data-email-form><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="purpose" value="link-email"><label>绑定邮箱<input name="email" type="email" required></label><button type="button" data-send-code class="secondary">发送验证码</button><p data-code-message role="status"></p><label>验证码<input name="code" required pattern="[0-9]{6}" autocomplete="one-time-code"></label><button>验证并绑定</button></form><?php endif ?></section><section class="card"><h2>登录方式</h2><p>微信：<?= $identities?'已绑定':'未绑定' ?></p><?php if(!$identities): ?><form method="post" action="/account/wechat"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><button class="secondary">绑定微信</button></form><?php endif ?><?php if($user['totp_secret']): ?><hr><a class="button secondary" href="/account/totp">管理二次验证</a><?php endif ?><p class="muted">敏感操作需要最近 5 分钟内完成登录验证。</p></section><section class="card"><h2><?= $user['password_hash']?'修改密码':'设置密码' ?></h2><form method="post" action="/account/password"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><?php if($user['password_hash']): ?><label>原密码<input type="password" name="old_password" autocomplete="current-password" required></label><?php endif ?><label>新密码<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><p class="muted">12～72 字节，包含大小写字母和数字。修改后需重新登录。</p><button>更新密码</button></form></section></div>